import React, {useState} from "react";
import Button from "@mui/material/Button";
import Menu from "@mui/material/Menu";
import MenuItem from "@mui/material/MenuItem";
import Dropdown from '@mui/base/Dropdown';
import { MenuButton } from '@mui/base/MenuButton';
import Menu2 from '@mui/base/Menu';
import MenuItem2 from '@mui/base/MenuItem';

      function DropdownMui() {
        const [anchorEl, setAnchorEl] = useState(null);

        const handleClick = (event) => {
          setAnchorEl(event.currentTarget);
        };
        const handleClose = () => {
          setAnchorEl(null);
        };

        return (
          <div>
            <Button
              aria-controls="simple-menu"
              aria-haspopup="true"
              onClick={handleClick}
              variant="contained"
              color="primary"
            >
              Menu
            </Button>
            <Menu2
              id="simple-menu"
              anchorEl={anchorEl}
              open={Boolean(anchorEl)}
              onClose={handleClose}
            >
              <MenuItem onClick={handleClose}><a href="/muffins">Muffins</a></MenuItem>
              <MenuItem onClick={handleClose}><a href="/cupcakes">Cupcakes</a></MenuItem>
              <MenuItem onClick={handleClose}><a href="/vegan">Vegan</a></MenuItem>
            </Menu2>
          </div>
        );
      }

export default DropdownMui;
